from research_helpers import *
a=ev('https://www.vandapharma.com/products-and-pipeline','Current issuer identifies six named oral product/formulation offerings with prescribing information, including separate Hetlioz capsules and Hetlioz LQ liquid.')
b=ev('https://www.sec.gov/Archives/edgar/data/1347178/000162828026053308/vnda8-k852026exhibit991.htm','August5 2026 issuer confirms May Nereus commercial launch, Bysanti FDA approval with launch still expected, and Quimilza imsidolimab BLA under review with December12 2026 target. Forecasts not treated as completed milestones.')
c=ev('https://vandapharma.com/pdfs/vanda_corporate_presentation_sep_26.pdf','September2026 issuer pipeline distinguishes oral products, investigational Fanapt long-acting injection, imsidolimab, CFTR modulators, HDAC inhibitor and antisense programmes. Chart stages not inferred from extracted phase-column headings.')
d=ev('https://www.prnewswire.com/news-releases/vanda-pharmaceuticals-provides-update-on-vqw-765-clinical-development-program-302909083.html','October14 2026 issuer release confirms VQW765 PhaseIII trial failed endpoints and programme is ON HOLD pending full-data analysis, not formally discontinued. Former AQW051 licensed from Novartis.');d['source']='issuer_press_release'
e=ev('https://www.sec.gov/Archives/edgar/data/1347178/000162828026031667/vnda-20260331.htm','2026 issuer filing names investigational VSJ110, VPO227, VTR297 and ASOs VGA157A, VCA894A, VGT1849A with targets/indications.')
ps=[]
for name,generic,desc,life in [('NEREUS','tradipitant','Oral NK1 receptor antagonist commercially launched May2026 for prevention of motion-induced vomiting.','commercial'),('BYSANTI','milsaperidone','Oral atypical antipsychotic approved for adult schizophrenia and acute manic/mixed bipolarI episodes; actual commercial launch not independently confirmed.','unknown'),('Fanapt','iloperidone','Oral atypical antipsychotic for adult schizophrenia and acute manic/mixed bipolarI episodes.','commercial'),('HETLIOZ','tasimelteon','Oral capsule melatonin-receptor agonist for Non24 and nighttime sleep disturbances in Smith-Magenis syndrome.','commercial'),('HETLIOZ LQ',None,'Separate tasimelteon oral suspension formulation for pediatric nighttime sleep disturbances in Smith-Magenis syndrome.','commercial'),('PONVORY','ponesimod','Oral S1P receptor modulator for relapsing forms of multiple sclerosis.','commercial')]:
 x=p(name,desc,a,life,typ='product',evidence=[a,b,c],attributes={'commercial_launch_verified':life=='commercial'})
 if generic:x['aliases']=[{'alias':generic,'alias_type':'generic_name'}]
 ps.append(x)
for name,desc in [('Fanapt long-acting injectable','Investigational long-acting injectable iloperidone formulation, distinct from oral Fanapt; PhaseIII schizophrenia programme.'),('Imsidolimab','Investigational anti-IL36-receptor antibody for generalized pustular psoriasis; BLA under FDA review with December12 2026 target, no approval claimed.'),('VSJ-110','Investigational CFTR activator for dry eye and ocular inflammation.'),('VPO-227','Investigational CFTR inhibitor for secretory diarrhea including cholera.'),('VTR-297','Investigational HDAC inhibitor for hematologic malignancies and onychomycosis.'),('VCA-894A','Investigational personalized antisense oligonucleotide for IGHMBP2 splice-variant Charcot-Marie-Tooth type2S.'),('VGA-157A','Investigational antisense oligonucleotide programme for Parkinson disease.'),('VGT-1849A','Investigational antisense oligonucleotide programme for polycythemia vera.')]:
 ps.append(p(name,desc,e,'development',aliases=['Quimilza'] if name=='Imsidolimab' else [],evidence=[e,c,b]))
ps.append(p('VQW-765','Alpha7 nicotinic acetylcholine receptor partial agonist for social/performance anxiety; programme on hold after failed PhaseIII study October14 2026.',d,'development',roles=['licensee'],aliases=['AQW-051'],attributes={'programme_activity':'on_hold','status_observed_date':'2026-10-14','trial_id':'NCT07221578'}))
ps.append(p('Vanda antisense oligonucleotide platform','Precision-medicine antisense oligonucleotide research platform supporting individually named investigational programmes.',c,'development',typ='technology',sub='research_tools',evidence=[c,e]))
cs=[company('Vanda Pharmaceuticals Inc.',ps,[a,b,c,d,e],'Six oral branded formulations, eight named investigational programmes, paused VQW765 and ASO platform reviewed. Bysanti FDA-approved but commercial launch unconfirmed; Quimilza is proposed imsidolimab brand with December2026 review date, not approved. VQW765 October14 hold supersedes September pipeline activity. Additional indication contexts, label strengths, territories, legacy programmes and any intervening licensing changes remain to research.')]
(out/'batch-0115.json').write_text(json.dumps({'companies':cs},indent=2));print(len(ps))
